<?php
/**
 * PixelMani: installs web/.htaccess WITHOUT a moment of public access.
 *
 * GENERATED by `npm run package:websupport` into install/ of the package,
 * with the expected SHA-256 of the package's web/.htaccess and a one-time
 * token. Upload it into web/ (under a name that contains the token) only for
 * the install; it deletes itself after a successful install.
 *
 * Why: uploading or renaming .htaccess by hand (WebFTP) either truncates the
 * active file or removes it for a while, and during that time the password
 * protection may be gone. This tool only ever makes the verified new file
 * appear with ONE rename() in the same directory. On Linux that is
 * rename(2): every request sees either no new file or the complete one.
 *
 * Two host layouts, detected (never assumed):
 *   web     the password gate is web/.htaccess itself. It is copied to a
 *           backup, then the new file is renamed OVER it atomically. Both
 *           carry the same password gate.
 *   parent  there is no web/.htaccess; the gate is the .htaccess of the
 *           folder ABOVE web/ (staging.pixelmani.se/.htaccess on the
 *           Websupport account), which Apache applies to everything below.
 *           The new file is renamed into the free name web/.htaccess. The
 *           parent gate stays in place and is never written, so it protects
 *           every moment before, during and after; the new file carries the
 *           same gate itself (Apache then uses the child's identical
 *           "Require valid-user", and it holds even if the parent gate is
 *           ever removed).
 *
 * It refuses unless:
 *   - the request itself came through HTTP Basic Auth (REMOTE_USER): the
 *     current gate is demonstrably active while this runs
 *   - the current gate (web/.htaccess, or else the parent's .htaccess) is
 *     exactly Websupport's plain Basic Auth gate, and .htaccess.new carries
 *     the same gate with the SAME password file (AuthUserFile)
 *   - .htaccess.new is byte for byte the package's web/.htaccess (SHA-256)
 *   - the server is POSIX (rename(2)) and the files are on one filesystem
 *   - every file it reads (.htaccess.new, the active web/.htaccess, the
 *     parent .htaccess, a backup) is a REGULAR file: lstat() never follows a
 *     link, and a symbolic link, folder or any other type is refused, even
 *     one pointing at the right bytes. The opened handle must be that same
 *     file (device + inode), so nothing is followed through a swapped path.
 *     Files it writes are created exclusively (fopen 'x'), never through an
 *     existing entry.
 *
 * Install: right before the rename, .htaccess.new is read again and must
 * still be the verified file (same device, inode and bytes). rename() moves
 * that directory entry itself. Afterwards web/.htaccess must be that very
 * inode with the expected SHA-256; if not, the install is undone (layout
 * "parent": the new entry is removed, so the unchanged parent gate alone
 * protects web/ again; layout "web": the verified previous file is put back).
 *
 * Trust assumption (unavoidable with rename(2), which has no "only if this
 * inode" form): whoever can write into web/ between the last check and the
 * rename (microseconds) could swap the entry. Only the hosting account's own
 * FTP login and its PHP can write there, and either could write
 * web/.htaccess directly anyway. A swap is detected and undone right after
 * the rename.
 *
 * The preflight folder is never deleted by this tool, and nothing in it is
 * ever overwritten. PHP can only reach files inside a folder through the
 * folder's path, and a path can be swapped for a link between any check and
 * a delete (a link to the folder above web/ would aim a delete at
 * Websupport's own .htaccess). So the preflight only CREATES: mkdir() (which
 * fails on any existing entry and never follows one) and exclusive files,
 * plus stamp.json with their identities. The install relies on it only after
 * lstat() shows a real folder whose identity and contents match that stamp,
 * and afterwards leaves it for manual deletion (DEPLOY.md step 7). The only
 * entries this tool ever deletes sit directly in web/: its own file, a
 * revert of web/.htaccess, its restore temp file.
 *
 * Actions (all text/plain, no paths, no secrets):
 *   ?action=check                       report only; changes nothing (default)
 *   ?action=preflight&confirm=TOKEN     creates pm-preflight-TOKEN/ holding the
 *                                       NEW .htaccess, probe.txt and stamp.json,
 *                                       to prove Apache accepts it here (401,
 *                                       then 200); an intact earlier one is reused
 *   ?action=install&confirm=TOKEN&preflight=passed
 *                                       (backup) + atomic install + self-delete;
 *                                       the preflight folder is left in place
 */

declare(strict_types=1);

const EXPECTED_SHA256 = '{{EXPECTED_SHA256}}';
const TOKEN = '{{TOKEN}}';
// Only true in a --local-test package (Windows test Apache). Never on the host.
const ALLOW_NON_POSIX = '{{ALLOW_NON_POSIX}}' === 'true';

header('Content-Type: text/plain; charset=utf-8');
header('Cache-Control: no-store');
header('X-Robots-Tag: noindex');
ini_set('display_errors', '0');

$dir = __DIR__;
$active = $dir . '/.htaccess';
$new = $dir . '/.htaccess.new';
// The folder above web/: on Websupport the account's own Basic Auth gate. Only ever read.
$parent = dirname($dir) . '/.htaccess';
$preflightDir = $dir . '/pm-preflight-' . TOKEN;
$report = [];
$problems = [];
$changed = false; // set once web/.htaccess was written

function note(string $line): void
{
    global $report;
    $report[] = $line;
}
function problem(string $line): void
{
    global $problems;
    $problems[] = $line;
    note("STOP  $line");
}
function finish(int $status = 200): never
{
    global $report, $problems, $changed;
    http_response_code($status);
    $stopped = $changed
        ? 'RESULT: STOPPED AFTER web/.htaccess WAS WRITTEN. Check the site in a private window now. Do NOT replace .htaccess by hand.'
        : 'RESULT: STOPPED. Nothing was changed. Do NOT replace .htaccess by hand.';
    echo "PixelMani .htaccess install\n\n" . implode("\n", $report) . "\n\n" . ($problems ? $stopped : 'RESULT: OK') . "\n";
    exit;
}

/**
 * The Basic Auth gate in an .htaccess: exactly one each of "Require
 * valid-user", "AuthType Basic", AuthName and AuthUserFile, and no other
 * Require/Satisfy/Allow line that could open access. Returns the
 * AuthUserFile line or null.
 */
function gateOf(string $text, bool $isPixelmani): ?string
{
    $lines = array_values(array_filter(array_map('trim', preg_split('/\r?\n/', $text)), static fn ($l) => $l !== '' && $l[0] !== '#'));
    $count = static fn (string $re) => count(array_filter($lines, static fn ($l) => preg_match($re, $l) === 1));
    if ($count('/^Require\s+valid-user$/i') !== 1 || $count('/^AuthType\s+Basic$/i') !== 1
        || $count('/^AuthName\s+"[^"]+"$/i') !== 1 || $count('/^AuthUserFile\s+\S.*$/i') !== 1) {
        return null;
    }
    foreach ($lines as $line) {
        if (preg_match('/^(Require|Satisfy|Allow|Order|AuthMerging)\b/i', $line)
            && !preg_match('/^Require\s+(valid-user|all\s+denied)$/i', $line)) {
            return null;
        }
    }
    if (!$isPixelmani && count($lines) !== 4) {
        return null; // Websupport's own file: the four lines and nothing else
    }
    foreach ($lines as $line) {
        if (preg_match('/^AuthUserFile\s+/i', $line)) {
            return $line;
        }
    }
    return null;
}

// File type bits of an lstat()/fstat() mode.
const FT_MASK = 0170000;
const FT_REGULAR = 0100000;
const FT_LINK = 0120000;
const FT_DIR = 0040000;

/**
 * Reads a file that must be a plain regular file, WITHOUT following links:
 *   - lstat() (which never follows a symbolic link) must report a regular
 *     file. A symbolic link (whatever it points to), a directory, a FIFO,
 *     socket or device, or an unknown type (e.g. a Windows reparse point)
 *     is refused.
 *   - the handle fopen() then gets must be that same file (device and inode
 *     from fstat()), so a path swapped for a link or another file between
 *     the two calls is caught, never followed.
 * Returns ['text', 'sha', 'dev', 'ino'] or a short reason (string).
 */
function readRegular(string $path): array|string
{
    clearstatcache(true, $path);
    $before = @lstat($path);
    if ($before === false) {
        return 'missing';
    }
    $type = $before['mode'] & FT_MASK;
    if ($type !== FT_REGULAR) {
        return match ($type) {
            FT_LINK => 'a symbolic link',
            FT_DIR => 'a directory',
            default => 'not a regular file',
        };
    }
    $handle = @fopen($path, 'rb');
    if ($handle === false) {
        return 'unreadable';
    }
    $opened = @fstat($handle);
    $text = @stream_get_contents($handle);
    fclose($handle);
    if ($opened === false || $text === false || ($opened['mode'] & FT_MASK) !== FT_REGULAR
        || $opened['dev'] !== $before['dev'] || $opened['ino'] !== $before['ino']) {
        return 'replaced while it was being read';
    }
    return ['text' => $text, 'sha' => hash('sha256', $text), 'dev' => $before['dev'], 'ino' => $before['ino']];
}

/** Whether anything at all (file, link, dangling link, folder …) exists at $path; links are not followed. */
function present(string $path): bool
{
    clearstatcache(true, $path);
    return @lstat($path) !== false;
}

/** Creates $path holding $bytes. Fails if anything exists there: O_CREAT|O_EXCL never follows a link. */
function createNew(string $path, string $bytes): bool
{
    $handle = @fopen($path, 'xb');
    if ($handle === false) {
        return false;
    }
    $ok = @fwrite($handle, $bytes) === strlen($bytes) && @fflush($handle);
    fclose($handle);
    return $ok;
}

const PROBE_TEXT = "pixelmani-preflight-ok\n";

/**
 * The preflight folder itself, by lstat(): a real folder, never a link,
 * junction or any other type. Returns [dev, ino] or a short reason.
 */
function preflightFolder(string $path): array|string
{
    clearstatcache(true, $path);
    $entry = @lstat($path);
    if ($entry === false) {
        return 'missing';
    }
    $type = $entry['mode'] & FT_MASK;
    if ($type !== FT_DIR) {
        return $type === FT_LINK ? 'a symbolic link' : 'not a plain folder (a link, a junction or another type)';
    }
    return [$entry['dev'], $entry['ino']];
}

/**
 * Whether the preflight folder can be relied on: the very folder the
 * preflight created (device + inode recorded in its stamp.json), holding
 * exactly its three regular files, unchanged since (each file's device,
 * inode and SHA-256 match the stamp; .htaccess is the package's file).
 * Reads only, never writes or deletes. Returns null, or the reason.
 */
function preflightProblem(string $path): ?string
{
    $folder = preflightFolder($path);
    if (is_string($folder)) {
        return "pm-preflight-<token> is $folder";
    }
    $stampRead = readRegular($path . '/stamp.json');
    $stamp = is_array($stampRead) ? json_decode($stampRead['text'], true) : null;
    if (!is_array($stamp) || ($stamp['dir'] ?? null) !== $folder) {
        return 'it is not the folder the preflight created (no valid stamp, or its identity differs)';
    }
    $gate = readRegular($path . '/.htaccess');
    $probe = readRegular($path . '/probe.txt');
    if (!is_array($gate) || !is_array($probe)) {
        return 'its .htaccess or probe.txt is missing or not a regular file';
    }
    if (($stamp['htaccess'] ?? null) !== [$gate['dev'], $gate['ino'], $gate['sha']] || !hash_equals(EXPECTED_SHA256, $gate['sha'])) {
        return 'its .htaccess changed since the preflight';
    }
    if (($stamp['probe'] ?? null) !== [$probe['dev'], $probe['ino'], $probe['sha']] || $probe['text'] !== PROBE_TEXT) {
        return 'its probe.txt changed since the preflight';
    }
    $entries = @scandir($path);
    $entries = $entries === false ? null : array_values(array_diff($entries, ['.', '..']));
    if ($entries !== ['.htaccess', 'probe.txt', 'stamp.json']) {
        return 'it holds other entries than the preflight wrote';
    }
    if (preflightFolder($path) !== $folder) {
        return 'the folder was replaced while it was being verified';
    }
    return null;
}

/** Same file and same bytes as an earlier readRegular() result. */
function sameFile(array|string $now, array $then): bool
{
    return is_array($now) && $now['dev'] === $then['dev'] && $now['ino'] === $then['ino'] && hash_equals($then['sha'], $now['sha']);
}

$action = (string) ($_GET['action'] ?? 'check');
if (!in_array($action, ['check', 'preflight', 'install'], true)) {
    problem('unknown action');
    finish(400);
}

// ---- 1. this request came through the password gate
// Only what Apache sets after a successful authentication counts. Not
// PHP_AUTH_USER: PHP fills that from any Authorization header the client
// sends, even where no gate is active, so it proves nothing.
$user = (string) ($_SERVER['REMOTE_USER'] ?? $_SERVER['REDIRECT_REMOTE_USER'] ?? '');
if ($user === '') {
    problem('this request did not come through HTTP Basic Auth (no REMOTE_USER from Apache): the current gate is not proven active');
} else {
    note('ok    this request is authenticated by the current password gate');
}

// ---- 2. where the current gate is, and that it is a plain Basic Auth gate
// Every file is read with readRegular(): links are refused, never followed.
$activeRead = null;
$activeGate = null;
$parentRead = null;
if (present($active)) {
    $layout = 'web';
    $activeRead = readRegular($active);
    if (is_string($activeRead)) {
        problem("the active web/.htaccess is $activeRead (it must be a regular file)");
    } else {
        $activeGate = gateOf($activeRead['text'], false) ?? gateOf($activeRead['text'], true);
        if ($activeGate === null) {
            problem('the active web/.htaccess is not a plain Basic Auth gate');
        } else {
            note('ok    layout "web": the active web/.htaccess carries the Basic Auth gate');
        }
    }
} elseif (present($parent)) {
    $layout = 'parent';
    $parentRead = readRegular($parent);
    if (is_string($parentRead)) {
        problem("there is no web/.htaccess, and the .htaccess above web/ is $parentRead (it must be a readable regular file)");
    } else {
        // Exactly Websupport's four lines: anything else (another Require,
        // Satisfy, AuthMerging …) could change what the gate means; stop.
        $activeGate = gateOf($parentRead['text'], false);
        if ($activeGate === null) {
            problem('there is no web/.htaccess, and the .htaccess above web/ is not exactly the four-line Basic Auth gate');
        } else {
            note('ok    layout "parent": no web/.htaccess yet; the folder above web/ carries the Basic Auth gate (only read, never changed)');
        }
    }
} else {
    $layout = 'none';
    problem('no password gate found: neither web/.htaccess nor an .htaccess in the folder above web/');
}

// ---- 3. the new file: the uploaded regular file, exactly the package's, with the same gate
$newRead = readRegular($new);
$newText = null;
if (is_string($newRead)) {
    problem($newRead === 'missing'
        ? 'web/.htaccess.new is missing (upload the package\'s web/.htaccess under that name first)'
        : "web/.htaccess.new is $newRead: only the uploaded regular file is accepted (no links, folders or other types)");
} else {
    $newText = $newRead['text'];
    if (!hash_equals(EXPECTED_SHA256, $newRead['sha'])) {
        problem('web/.htaccess.new is not byte for byte the package\'s web/.htaccess (SHA-256 differs: incomplete or wrong upload)');
    } else {
        note('ok    web/.htaccess.new is a regular file and matches the package (SHA-256)');
    }
    if (!str_starts_with($newText, "Require valid-user\n")) {
        problem('web/.htaccess.new does not start with "Require valid-user"');
    }
    $newGate = gateOf($newText, true);
    if ($newGate === null || $activeGate === null || !hash_equals($activeGate, $newGate)) {
        problem('web/.htaccess.new does not carry the SAME password gate (AuthUserFile) as the current gate');
    } else {
        note('ok    the new file and the current gate use the same password file');
    }
}

// ---- 4. atomic replacement is available
$posix = PHP_OS_FAMILY !== 'Windows';
if (!$posix && !ALLOW_NON_POSIX) {
    problem('not a POSIX server: rename() is not guaranteed to replace atomically here');
} else {
    note($posix ? 'ok    POSIX rename(2): replaces the target atomically' : 'note  LOCAL TEST on Windows (not the host): MoveFileEx replace');
}
$dirStat = @lstat($dir);
if (is_array($newRead) && ($dirStat === false || $newRead['dev'] !== $dirStat['dev'])) {
    problem('.htaccess.new and web/ are not on the same filesystem');
}
if (!is_writable($dir)) {
    problem('PHP cannot write to web/');
}

if ($action === 'check') {
    note($problems ? '' : 'ready: run ?action=preflight&confirm=<token> next');
    finish($problems ? 409 : 200);
}

// ---- actions that change something
if (!hash_equals(TOKEN, (string) ($_GET['confirm'] ?? ''))) {
    problem('missing or wrong confirm token');
    finish(403);
}
if ($problems) {
    finish(409);
}

if ($action === 'preflight') {
    // This action only ever CREATES. It never deletes or rewrites anything:
    // an existing preflight folder is verified and reused, or refused.
    if (preflightFolder($preflightDir) !== 'missing') {
        $why = preflightProblem($preflightDir);
        if ($why !== null) {
            problem("an earlier preflight folder exists but cannot be used: $why. Nothing was changed; delete it by hand (DEPLOY.md step 7, cleanup), then run the preflight again");
            finish(409);
        }
        note('ok    the preflight folder of an earlier run is intact (verified, reused; nothing written)');
    } else {
        // mkdir() fails if ANY entry exists at that name (a link included) and never follows one.
        if (!@mkdir($preflightDir, 0755)) {
            problem('could not create the preflight folder');
            finish(500);
        }
        $made = preflightFolder($preflightDir);
        // Exclusive creation only (O_CREAT|O_EXCL): nothing that exists is ever
        // overwritten, through a link or otherwise. The folder gets its OWN gate
        // (the verified bytes) before its probe exists.
        $ok = is_array($made) && createNew($preflightDir . '/.htaccess', (string) $newText) && createNew($preflightDir . '/probe.txt', PROBE_TEXT);
        $gate = $ok ? readRegular($preflightDir . '/.htaccess') : 'not written';
        $probe = $ok ? readRegular($preflightDir . '/probe.txt') : 'not written';
        // stamp.json records what this run created, so the install can tell it apart from anything else.
        $ok = $ok && is_array($gate) && is_array($probe) && preflightFolder($preflightDir) === $made
            && createNew($preflightDir . '/stamp.json', json_encode([
                'dir' => $made,
                'htaccess' => [$gate['dev'], $gate['ino'], $gate['sha']],
                'probe' => [$probe['dev'], $probe['ino'], $probe['sha']],
            ]) . "\n");
        $why = $ok ? preflightProblem($preflightDir) : 'its files could not be written';
        if ($why !== null) {
            problem("the new preflight folder is not usable: $why. Nothing else was changed; delete it by hand (DEPLOY.md step 7, cleanup), then run the preflight again");
            finish(500);
        }
        note('ok    preflight folder created with the NEW .htaccess (stamp.json records its identity)');
    }
    note('next: open /pm-preflight-' . TOKEN . '/probe.txt in a PRIVATE window:');
    note('      without the password it must ask for one (401); with it, it must show "pixelmani-preflight-ok".');
    note('      A 500 means Apache refuses a directive here: STOP and report it.');
    note('      Then: ?action=install&confirm=<token>&preflight=passed');
    finish();
}

// install
if (($_GET['preflight'] ?? '') !== 'passed' || preflightFolder($preflightDir) === 'missing') {
    problem('run the preflight first and confirm it with preflight=passed');
    finish(409);
}
// The preflight result counts only for the very folder the preflight created, unchanged.
$preflightWhy = preflightProblem($preflightDir);
if ($preflightWhy !== null) {
    problem("the preflight folder cannot be relied on: $preflightWhy. Nothing installed; delete it by hand (DEPLOY.md step 7, cleanup) and run the preflight again");
    finish(409);
}
note('ok    preflight folder verified: a real folder, the one the preflight created, unchanged');
// The current gate must still be exactly what was verified above.
if ($layout === 'web' && !sameFile(readRegular($active), $activeRead)) {
    problem('the active web/.htaccess changed since it was verified; nothing installed (run check again)');
    finish(409);
}
if ($layout === 'parent' && !sameFile(readRegular($parent), $parentRead)) {
    problem('the .htaccess above web/ changed since it was verified; nothing installed (run check again)');
    finish(409);
}
if ($layout === 'web') {
    // Backup: a new COPY of the verified bytes (never a copy through a link);
    // the active file stays in place until the atomic rename.
    $backup = $dir . '/.htaccess.websupport-backup';
    $earlier = present($backup) ? readRegular($backup) : null;
    if (is_array($earlier) && hash_equals($earlier['sha'], $activeRead['sha'])) {
        note('ok    backup already present: ' . basename($backup));
    } else {
        if ($earlier !== null) {
            $backup = $dir . '/.htaccess.backup-' . gmdate('Ymd-His') . '-' . bin2hex(random_bytes(3));
        }
        $written = createNew($backup, $activeRead['text']) ? readRegular($backup) : 'not written';
        if (!is_array($written) || !hash_equals($written['sha'], $activeRead['sha'])) {
            problem('could not write a verified backup of the active .htaccess; nothing replaced');
            finish(500);
        }
        note('ok    backup written: ' . basename($backup));
    }
} else {
    // Parent layout: nothing in web/ to back up, and the parent file is never
    // written. The target name must still be free (it was at the check).
    if (present($active)) {
        problem('web/.htaccess appeared since the check; nothing installed (run check again)');
        finish(409);
    }
    note('ok    web/.htaccess is still free; the parent gate stays active throughout');
}
// The file renamed below must be the one verified above: same file (device,
// inode) and same bytes, read again just before. rename() moves the
// directory entry itself and never follows a link.
if (!sameFile(readRegular($new), $newRead)) {
    problem('web/.htaccess.new changed since it was verified; nothing installed (run check again)');
    finish(409);
}

// One rename() of the verified file into web/.htaccess. A failed attempt
// changes nothing (the old state stays complete), so a short retry is safe;
// it matters on Windows, where a file another process holds open cannot be
// renamed at that instant.
$renamed = false;
$attempts = ALLOW_NON_POSIX ? 400 : 40;
for ($attempt = 0; $attempt < $attempts && !$renamed; $attempt++) {
    $renamed = @rename($new, $active);
    if (!$renamed) {
        usleep(ALLOW_NON_POSIX ? 10000 : 50000);
    }
}
if (!$renamed) {
    problem($layout === 'web'
        ? 'rename failed; the active .htaccess is unchanged (safe to run install again)'
        : 'rename failed; web/.htaccess was not created, the parent gate is unchanged (safe to run install again)');
    finish(500);
}
$changed = true;

// What is in place now must be the verified file itself: a regular file, the
// same device and inode as checked, the expected SHA-256. Anything else (the
// incoming name was swapped between the last check and the rename) is undone.
$installed = readRegular($active);
if (!sameFile($installed, $newRead) || !hash_equals(EXPECTED_SHA256, $installed['sha'])) {
    $why = is_string($installed) ? $installed : 'not the verified file';
    if ($layout === 'parent') {
        // Back to the verified safe state: no web/.htaccess, the parent gate alone.
        $undone = @unlink($active) && !present($active);
        problem($undone
            ? "the installed web/.htaccess was $why; it was removed again, so the unchanged parent gate alone protects web/ as before"
            : "the installed web/.htaccess is $why and could not be removed: check immediately");
    } else {
        // Put the verified previous file back with one rename().
        $restore = $dir . '/.htaccess.restore-' . TOKEN;
        if (present($restore)) {
            @unlink($restore);
        }
        $back = createNew($restore, $activeRead['text']) && @rename($restore, $active) ? readRegular($active) : 'not restored';
        $undone = is_array($back) && hash_equals($activeRead['sha'], $back['sha']);
        problem($undone
            ? "the installed web/.htaccess was $why; the previous web/.htaccess was put back"
            : "the installed web/.htaccess is $why and the previous one could not be put back: check immediately");
    }
    finish(500);
}
if ($layout === 'parent') {
    if (!sameFile(readRegular($parent), $parentRead)) {
        problem('the .htaccess above web/ is not what it was at the check (this tool never writes it): check immediately');
        finish(500);
    }
    note('ok    web/.htaccess created atomically: a regular file, the verified file itself, the package\'s bytes, the same gate as the parent');
    note('ok    the .htaccess above web/ is unchanged (it stays in place as the outer gate)');
} else {
    note('ok    web/.htaccess replaced atomically: a regular file, the verified file itself, the package\'s bytes (with the same gate)');
}

// The preflight folder is NOT deleted by this tool, on purpose. PHP can only
// delete the files in it through the folder's path, and between any check and
// a delete that path could be swapped for a link (for example to the folder
// above web/, where Websupport's .htaccess and .htpasswd are). It holds only
// a copy of the new gate, probe.txt and stamp.json, and is behind the gate.
note('LEFT  the preflight folder pm-preflight-' . TOKEN . '/ is left in place on purpose: this tool never deletes through a folder.');
note('      Delete it by hand (DEPLOY.md step 7, cleanup). Until then it is harmless: behind the password, a copy of the gate.');

// This tool's own entry, directly in web/ (not through any subfolder):
// unlink() removes the entry itself and never follows a link.
$self = $dir . '/' . basename(__FILE__);
$selfEntry = @lstat($self);
$selfFile = @stat(__FILE__);
$deleted = $selfEntry !== false && $selfFile !== false && ($selfEntry['mode'] & FT_MASK) === FT_REGULAR
    && $selfEntry['dev'] === $selfFile['dev'] && $selfEntry['ino'] === $selfFile['ino'] && @unlink($self);
note($deleted ? 'ok    this tool deleted itself' : 'WARN  could not delete this tool: delete it by hand (the new rules already refuse to run it)');
finish();
